const WD=['Ð²Ñ','Ð¿Ð½','Ð²Ñ‚','ÑÑ€','Ñ‡Ñ‚','Ð¿Ñ‚','ÑÐ±'],MON=['ÑÐ½Ð²Ð°Ñ€Ñ','Ñ„ÐµÐ²Ñ€Ð°Ð»Ñ','Ð¼Ð°Ñ€Ñ‚Ð°','Ð°Ð¿Ñ€ÐµÐ»Ñ','Ð¼Ð°Ñ','Ð¸ÑŽÐ½Ñ','Ð¸ÑŽÐ»Ñ','Ð°Ð²Ð³ÑƒÑÑ‚Ð°','ÑÐµÐ½Ñ‚ÑÐ±Ñ€Ñ','Ð¾ÐºÑ‚ÑÐ±Ñ€Ñ','Ð½Ð¾ÑÐ±Ñ€Ñ','Ð´ÐµÐºÐ°Ð±Ñ€Ñ'],MONN=['Ð¯Ð½Ð²Ð°Ñ€ÑŒ','Ð¤ÐµÐ²Ñ€Ð°Ð»ÑŒ','ÐœÐ°Ñ€Ñ‚','ÐÐ¿Ñ€ÐµÐ»ÑŒ','ÐœÐ°Ð¹','Ð˜ÑŽÐ½ÑŒ','Ð˜ÑŽÐ»ÑŒ','ÐÐ²Ð³ÑƒÑÑ‚','Ð¡ÐµÐ½Ñ‚ÑÐ±Ñ€ÑŒ','ÐžÐºÑ‚ÑÐ±Ñ€ÑŒ','ÐÐ¾ÑÐ±Ñ€ÑŒ','Ð”ÐµÐºÐ°Ð±Ñ€ÑŒ'];
const today0=()=>{const t=new Date();t.setHours(0,0,0,0);return t};
function days(n){const out=[],t=today0();for(let i=1;i<=n;i++){const d=new Date(t);d.setDate(t.getDate()+i);out.push(d)}return out}
const iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const fromIso=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)};
const human=d=>d.getDate()+' '+MON[d.getMonth()]+', '+WD[d.getDay()];
const shortDate=s=>{const d=fromIso(s);return d.getDate()+' '+MON[d.getMonth()].slice(0,3)+', '+WD[d.getDay()]};
