function tourGalleryHTML(pics){return `<div class="gallery tour-gallery" style="--gallery-rows:${Math.max(1,pics.length-1)}">${pics.map((p,i)=>`<button type="button" data-lb="${i}" ${i===0?'data-gallery-main':'data-gallery-thumb'} aria-label="ÐžÑ‚ÐºÑ€Ñ‹Ñ‚ÑŒ Ñ„Ð¾Ñ‚Ð¾ ${i+1}"><img src="${esc(p)}" alt="Ð¤Ð¾Ñ‚Ð¾ ÑÐºÑÐºÑƒÑ€ÑÐ¸Ð¸ ${i+1}">${i===0?`<img class="gallery-preview" alt="" aria-hidden="true"><span class="count">${pics.length} Ñ„Ð¾Ñ‚Ð¾</span>`:''}</button>`).join('')}</div>`}
function previewTourPhoto(button,show){const gallery=button.closest('.tour-gallery'),main=$('[data-gallery-main]',gallery),preview=$('.gallery-preview',main);if(!main||!preview)return;if(show){preview.src=$('img',button).src;preview.classList.add('on');main.dataset.lb=button.dataset.lb;main.setAttribute('aria-label','ÐžÑ‚ÐºÑ€Ñ‹Ñ‚ÑŒ Ñ„Ð¾Ñ‚Ð¾ '+(Number(button.dataset.lb)+1))}else{preview.classList.remove('on');main.dataset.lb='0';main.setAttribute('aria-label','ÐžÑ‚ÐºÑ€Ñ‹Ñ‚ÑŒ Ñ„Ð¾Ñ‚Ð¾ 1')}}
document.addEventListener('pointerover',e=>{if(e.pointerType!=='mouse')return;const button=e.target.closest('[data-gallery-thumb]');if(button&&!button.contains(e.relatedTarget))previewTourPhoto(button,true)});
document.addEventListener('pointerout',e=>{if(e.pointerType!=='mouse')return;const button=e.target.closest('[data-gallery-thumb]');if(button&&!button.contains(e.relatedTarget))previewTourPhoto(button,false)});
document.addEventListener('focusin',e=>{const button=e.target.closest('[data-gallery-thumb]');if(button)previewTourPhoto(button,true)});
document.addEventListener('focusout',e=>{const button=e.target.closest('[data-gallery-thumb]');if(button)previewTourPhoto(button,false)});

/* ---------- Lightbox ---------- */
function lightbox(pics,i){
 if(!pics.length)return;i=((Number(i)||0)%pics.length+pics.length)%pics.length;
 const lb=document.createElement('div');lb.className='lightbox photo-lightbox';lb.setAttribute('role','dialog');lb.setAttribute('aria-modal','true');lb.setAttribute('aria-label','Ð¤Ð¾Ñ‚Ð¾');
 const n=pics.length;
 const draw=()=>{lb.innerHTML=`<div class="lb-top"><span class="num">${i+1} / ${n}</span><button class="circle" type="button" data-lbx aria-label="Ð—Ð°ÐºÑ€Ñ‹Ñ‚ÑŒ">âœ•</button></div><div class="lb-img"><img src="${esc(pics[i])}" alt="Ð¤Ð¾Ñ‚Ð¾ ${i+1}"></div><div class="lb-nav" ${n<2?'hidden':''}><button class="circle lb-prev" type="button" data-lbn="-1" aria-label="ÐŸÑ€ÐµÐ´Ñ‹Ð´ÑƒÑ‰ÐµÐµ">${ICON.left}</button><button class="circle lb-next" type="button" data-lbn="1" aria-label="Ð¡Ð»ÐµÐ´ÑƒÑŽÑ‰ÐµÐµ">${ICON.right}</button></div>`;$('[data-lbx]',lb).focus()};
 const close=()=>{lb.remove();document.removeEventListener('keydown',key)};
 const key=e=>{if(e.key==='Escape')close();if(e.key==='ArrowRight'){i=(i+1)%n;draw()}if(e.key==='ArrowLeft'){i=(i-1+n)%n;draw()}};
 lb.addEventListener('click',e=>{if(e.target.closest('[data-lbx]')||e.target===lb)return close();const b=e.target.closest('[data-lbn]');if(b){i=(i+Number(b.dataset.lbn)+n)%n;draw();return}const image=$('.lb-img img',lb);if(!e.target.closest('img,button')||photoBackdropClick(e,image))close()});
 let x0=null;lb.addEventListener('touchstart',e=>{x0=e.touches[0].clientX},{passive:true});lb.addEventListener('touchend',e=>{if(x0===null)return;const dx=e.changedTouches[0].clientX-x0;if(Math.abs(dx)>40){i=(i+(dx<0?1:-1)+n)%n;draw()}x0=null});
 document.addEventListener('keydown',key);document.body.appendChild(lb);draw();
}

