let dlNs;const dlReady=(window.claude&&typeof window.claude.use==='function')?window.claude.use('downloads').then(n=>{dlNs=n;return n}).catch(()=>null):Promise.resolve(null);
async function download(name,data,type){
 const ns=dlNs!==undefined?dlNs:await dlReady;
 if(ns){try{await ns.save({filename:name,data:new Blob([data],{type})});toast('Ð¤Ð°Ð¹Ð» ÑÐ¾Ñ…Ñ€Ð°Ð½Ñ‘Ð½')}catch(e){if(e&&e.code!=='declined')toast('ÐÐµ ÑƒÐ´Ð°Ð»Ð¾ÑÑŒ ÑÐ¾Ñ…Ñ€Ð°Ð½Ð¸Ñ‚ÑŒ Ñ„Ð°Ð¹Ð»')}return}
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
